@@ -1,9 +1,142 @@
+type Triple = [bigint, bigint, bigint];
+type Bound = { op: ">=" | ">" | "<=" | "<" | "="; v: Triple };
+type Partial = { n: number; v: Triple };
+
+const VERSION_RE = /^(\d+)\.(\d+)\.(\d+)$/;
+const PARTIAL_RE = /^(\d+|[xX*])(?:\.(\d+|[xX*])(?:\.(\d+|[xX*]))?)?$/;
+const COMPARATOR_RE = /^(>=|<=|>|<|=|~|\^)?(.*)$/;
+
+function parseVersion(version: string): Triple {
+  const m = VERSION_RE.exec(version);
+  if (!m) throw new Error(`Invalid version: ${JSON.stringify(version)}`);
+  return [BigInt(m[1]), BigInt(m[2]), BigInt(m[3])];
+}
+
+function compare(a: Triple, b: Triple): number {
+  for (let i = 0; i < 3; i++) {
+    if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1;
+  }
+  return 0;
+}
+
+// n is the number of leading numeric parts; missing or wildcard parts are zero in v.
+function parsePartial(text: string): Partial {
+  const m = PARTIAL_RE.exec(text);
+  if (!m) throw new Error(`Invalid version in range: ${JSON.stringify(text)}`);
+  const v: Triple = [0n, 0n, 0n];
+  let n = 0;
+  let wildcard = false;
+  for (let i = 0; i < 3; i++) {
+    const part = m[i + 1];
+    if (part === undefined) {
+      wildcard = true;
+    } else if (/^\d+$/.test(part)) {
+      if (wildcard) throw new Error(`Invalid version in range: ${JSON.stringify(text)}`);
+      v[i] = BigInt(part);
+      n++;
+    } else {
+      wildcard = true;
+    }
+  }
+  return { n, v };
+}
+
+// First version above everything the partial names: 1
